// TAGDROP hand-in program, written for this entry.
// Running it assembles the deliverable in one place: the static
// site from app/, the captures from screenshots/, plus a dossier
// summary generated by the vendored frontend helper.

import { buildDossier } from './vendor/makefun-frontend.ts';
import { cpSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const LIMITS = {
  text_max_bytes: 163840,
  screenshots: { max: 4, max_bytes: 262144 },
  app_max_files: 993,
  app_max_bytes: 16777216,
};

function repoRoot() {
  return dirname(fileURLToPath(import.meta.url));
}

function targetDir() {
  const fromEnv = process.env.MAKEFUN_OUTPUT_DIR;
  return fromEnv && fromEnv.length > 0 ? fromEnv : '/output';
}

function placeFolder(source, destination) {
  // Create the target first so a missing screenshots folder in
  // the output never breaks the copy that follows it.
  mkdirSync(destination, { recursive: true });
  cpSync(source, destination, { recursive: true });
}

function emitDossier(where) {
  // The caps below mirror the gate for this bounty: they stop
  // an oversize hand-in here instead of letting the scorer do it.
  writeFileSync(join(where, 'dossier.json'), buildDossier(where, LIMITS));
}

function deliver() {
  const base = repoRoot();
  const dest = targetDir();

  mkdirSync(dest, { recursive: true });
  placeFolder(join(base, 'app'), join(dest, 'app'));

  const shotsAtRepo = join(base, 'screenshots');
  const shotsAtDest = join(dest, 'screenshots');
  mkdirSync(shotsAtDest, { recursive: true });
  if (existsSync(shotsAtRepo)) {
    cpSync(shotsAtRepo, shotsAtDest, { recursive: true });
  }

  emitDossier(dest);
}

deliver();
